sql.where:
a.tenant_id = #{q.tenantId}

    AND a.action_type = #{q.actionType}


    AND a.event_id = #{q.eventId}


    AND a.host_id = #{q.hostId}


    AND a.operator_username LIKE CONCAT('%', #{q.operatorUsername}, '%')


    AND a.target_username LIKE CONCAT('%', #{q.targetUsername}, '%')


    AND (a.operator_username LIKE CONCAT('%', #{q.keyword}, '%')
         OR a.target_username LIKE CONCAT('%', #{q.keyword}, '%')
         OR a.details LIKE CONCAT('%', #{q.keyword}, '%'))


    AND a.event_time >= #{q.startTime}


    AND a.event_time <= #{q.endTime}

mapper.select:
SELECT COUNT(1)
FROM account_change_logs
WHERE action_type = #{action}
  AND tenant_id = #{tenantId}
  AND DATE(event_time) = CURDATE()
